// The fields of the grammar yql, as Node.ChildByFieldID takes them. The
// comment of each one is its name.
const (
	FieldAlias      transit.FieldID = 1  // "alias"
	FieldBody       transit.FieldID = 2  // "body"
	FieldCondition  transit.FieldID = 3  // "condition"
	FieldDefault    transit.FieldID = 4  // "default"
	FieldFunction   transit.FieldID = 5  // "function"
	FieldHigh       transit.FieldID = 6  // "high"
	FieldIndex      transit.FieldID = 7  // "index"
	FieldLeft       transit.FieldID = 8  // "left"
	FieldLow        transit.FieldID = 9  // "low"
	FieldMember     transit.FieldID = 10 // "member"
	FieldObject     transit.FieldID = 11 // "object"
	FieldOperand    transit.FieldID = 12 // "operand"
	FieldOperator   transit.FieldID = 13 // "operator"
	FieldParameters transit.FieldID = 14 // "parameters"
	FieldPattern    transit.FieldID = 15 // "pattern"
	FieldResult     transit.FieldID = 16 // "result"
	FieldRight      transit.FieldID = 17 // "right"
	FieldType       transit.FieldID = 18 // "type"
	FieldValue      transit.FieldID = 19 // "value"
	FieldWindow     transit.FieldID = 20 // "window"
)

// The short names of the types of the tables.
type (
	action = abi.ParseAction
	header = abi.EntryHeader
	shift  = abi.ShiftAction
	reduce = abi.ReduceAction
)

